sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    // Don't run when the form is loading or if the field is cleared.
    if (isLoading || newValue === '') {
        return;
    }

    // Get the parent case sys_id.
    var parentCaseSysId = g_form.getValue("aml_kyc_case");

    // If there is no parent case, no validation is needed.
    if (!parentCaseSysId) {
        return;
    }

    // Asynchronously retrieve the parent case record.
    g_form.getReference("aml_kyc_case", function(parentCase) {
        if (parentCase) {
            var parentAssignedTo = parentCase.assigned_to;

            // Check if the new assignee is the same as the parent's assignee.
            if (newValue === parentAssignedTo) {
                // 1. Display an error message to the user.
                g_form.addErrorMessage("Maker and Checker cannot be the same person. The assignment has been reverted.");

                // 2. "Abort" the action by clearing the invalid value.
                // This prevents the user from saving the invalid state.
                g_form.setValue('assigned_to', '');
            }
        }
    });
}
